import unicodedata
from typing import Any, List, Optional


def _is_java_identifier_part(c: str) -> bool:
    if len(c) != 1:
        return False
    cat = unicodedata.category(c)
    if cat in ('Lu', 'Ll', 'Lt', 'Lm', 'Lo', 'Nl', 'Nd', 'Sc', 'Pc', 'Mc', 'Mn', 'Cf'):
        return True
    code = ord(c)
    if (0x0000 <= code <= 0x0008) or (0x000E <= code <= 0x001B) or (0x007F <= code <= 0x009F):
        return True
    return False


def _is_valid_opt(c: str) -> bool:
    return _is_java_identifier_part(c) or c in ('?', '@')


def _is_valid_char(c: str) -> bool:
    return _is_java_identifier_part(c) or c == '-'


def _validate_option(opt: Optional[str]) -> Optional[str]:
    if opt is None:
        return None
    if len(opt) == 0:
        raise ValueError("Empty option name.")
    ch0 = opt[0]
    if not _is_valid_opt(ch0):
        raise ValueError(f"Illegal option name '{ch0}'.")
    for ch in opt[1:]:
        if not _is_valid_char(ch):
            raise ValueError(f"The option '{opt}' contains an illegal character : '{ch}'.")
    return opt


def _strip_leading_hyphens(s: Optional[str]) -> Optional[str]:
    if not s:
        return s
    if s.startswith("--"):
        return s[2:]
    if s.startswith("-"):
        return s[1:]
    return s


def _strip_leading_and_trailing_quotes(s: Optional[str]) -> Optional[str]:
    if not s:
        return s
    length = len(s)
    if length > 1 and s.startswith('"') and s.endswith('"') and '"' not in s[1:-1]:
        return s[1:-1]
    return s


